from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

G = 7  # groups
S = 5  # size
W = 5  # weeks
N = G * S  # 35

vpool = IDPool()
def x(w, p, g):
    return vpool.id(('x', w, p, g))
def y(w, p, q):  # p<q, same group in week w
    return vpool.id(('y', w, p, q))

clauses = []

# Each player in exactly one group per week
for w in range(W):
    for p in range(N):
        lits = [x(w,p,g) for g in range(G)]
        # exactly one
        cnf = CardEnc.equals(lits=lits, bound=1, vpool=vpool, encoding=EncType.pairwise)
        clauses.extend(cnf.clauses)

# Each group has exactly S players
for w in range(W):
    for g in range(G):
        lits = [x(w,p,g) for p in range(N)]
        cnf = CardEnc.equals(lits=lits, bound=S, vpool=vpool, encoding=EncType.seqcounter)
        clauses.extend(cnf.clauses)

# y(w,p,q) iff exists g with x(w,p,g) and x(w,q,g)
# Define: y -> OR of (x_pg AND x_qg). Actually we want: if p,q in same group in week w, then y=1.
# We need constraint: for each pair (p,q), sum_w y(w,p,q) <= 1.
# And we need y(w,p,q) = 1 when they're together.
# Use: for each g, x(w,p,g) AND x(w,q,g) -> y(w,p,q)
for w in range(W):
    for p in range(N):
        for q in range(p+1, N):
            for g in range(G):
                clauses.append([-x(w,p,g), -x(w,q,g), y(w,p,q)])

# At most one week together per pair
for p in range(N):
    for q in range(p+1, N):
        lits = [y(w,p,q) for w in range(W)]
        cnf = CardEnc.atmost(lits=lits, bound=1, vpool=vpool, encoding=EncType.seqcounter)
        clauses.extend(cnf.clauses)

# Symmetry breaking: week 0 fixed
for p in range(N):
    g = p // S
    clauses.append([x(0, p, g)])

# Week 1: player 0 in group 0, player 1 in group 1, ..., player 6 in group... Actually let's fix week 1 player p: first players of each group.
# Fix players 0..6 in week 1: player i in group i
for i in range(G):
    clauses.append([x(1, i, i)])

solver = Glucose4()
for c in clauses:
    solver.add_clause(c)

print("solving...")
res = solver.solve()
print(res)
if res:
    model = set(solver.get_model())
    sched = [0]*(W*N)
    for w in range(W):
        for p in range(N):
            for g in range(G):
                if x(w,p,g) in model:
                    sched[w*N+p] = g
    # verify
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(N):
            groups[sched[w*N+p]].append(p)
        assert all(len(gr)==S for gr in groups), groups
    pairs = {}
    for w in range(W):
        groups = [[] for _ in range(G)]
        for p in range(N):
            groups[sched[w*N+p]].append(p)
        for gr in groups:
            for i in range(len(gr)):
                for j in range(i+1,len(gr)):
                    pr = (gr[i],gr[j])
                    pairs[pr] = pairs.get(pr,0)+1
    assert all(v<=1 for v in pairs.values())
    print("verified")
    print(sched)
